using Godot;

/// <summary>The game's system font as J2D draws it (JUTResFont over standard_fontEx.bfn): one glyph sheet, 20 x 20 cells, and per code
/// the WID1 entry -- Kern (field_0x0, skipped for the first glyph of a run) and Advance (field_0x1, the glyph's width). A text box
/// draws each glyph as its whole CELL (drawChar_scale: cellWidth x cellHeight at fontSize / Width, the top at the baseline - Ascent),
/// with the sheet's intensity as alpha on the box's white colour (setBlackWhite 0xFFFFFF00 / 0xFFFFFFFF). Generated by
/// tools/projectshine/gen_talk_assets.py into TalkFont.tres; to swap the font, point Page at another sheet and fill the arrays.</summary>
[GlobalClass]
public partial class SmsTalkFont : Resource
{
    [Export] public Texture2D Page;
    [Export] public int CellWidth = 20, CellHeight = 20;
    [Export] public int Width = 20, Ascent = 20, Descent = 0, Leading = 20;   // INF1
    [Export] public int FirstCode = 32;
    [Export] public int[] CellX = System.Array.Empty<int>();
    [Export] public int[] CellY = System.Array.Empty<int>();
    [Export] public int[] Kern = System.Array.Empty<int>();
    [Export] public int[] Advance = System.Array.Empty<int>();

    public bool Has(char c)
    {
        int i = c - FirstCode;
        return i >= 0 && i < Advance.Length && Page != null;
    }

    /// <summary>getWidthEntry: (kern, advance); a code the font lacks reads as (0, Width), as JUTResFont does.</summary>
    public void WidthEntry(char c, out int kern, out int advance)
    {
        int i = c - FirstCode;
        if (i < 0 || i >= Advance.Length) { kern = 0; advance = Width; return; }
        kern = Kern[i]; advance = Advance[i];
    }

    /// <summary>The glyph's cell on the sheet (loadImage).</summary>
    public Rect2 Cell(char c)
    {
        int i = c - FirstCode;
        if (i < 0 || i >= CellX.Length) i = 0;
        return new Rect2(CellX[i], CellY[i], CellWidth, CellHeight);
    }
}
